 const orderForm='<form id="mfg-order"><div class="two"><label>Style number<input name="style" required></label><label>Product<input name="product" required placeholder="Boys kurta set"></label></div><div class="two"><label>Colour<input name="colour"></label><label>Quantity (pcs)<input name="qty" type="number" min="1" step="1" required></label></div><label>Size-wise plan<input name="sizes" placeholder="20:10, 22:20, 24:30"></label><div class="two"><label>Target date<input name="due" type="date"></label><label>Priority<select name="priority"><option>Normal</option><option>Urgent</option><option>Low</option></select></label></div><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="primary">Create production order</button></form>';
 const sampleForm='<form id="mfg-sample"><div class="two"><label>Style number<input name="style" required></label><label>Sample type<select name="type"><option>First sample</option><option>Fit sample</option><option>Size set</option><option>Pre-production sample</option></select></label></div><label>Status<select name="status"><option>In progress</option><option>Submitted for approval</option><option>Approved</option><option>Rejected / revise</option></select></label><label>Comments<input name="notes"></label><button class="secondary">Save sample</button></form>';
 const sampleRows=ss.slice().reverse().map(s=>'<div class="line"><b>'+esc(s.style)+' · '+esc(s.type)+'</b><span class="tag">'+esc(s.status)+'</span></div>').join('');
