function bindMfg(){const f=document.getElementById('mfg-order');if(f)f.onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(f));o.qty=Number(o.qty);if(!Number.isInteger(o.qty)||o.qty<1){alert('Enter a whole number quantity.');return;}o.id='PO-'+Date.now();o.progress={};o.history=[];mfg.orders.push(o);saveMfg();render();};const s=document.getElementById('mfg-sample');if(s)s.onsubmit=e=>{e.preventDefault();mfg.samples.push(Object.fromEntries(new FormData(s)));saveMfg();render();};document.querySelectorAll('.mfg-stage').forEach(f=>f.onsubmit=e=>{e.preventDefault();const o=mfg.orders.find(x=>x.id===f.dataset.id),d=Object.fromEntries(new FormData(f));if(!o)return;const q=Number(d.qty),old=Number(o.progress[d.stage]||0);if(!Number.isInteger(q)||q<1||old+q>o.qty){alert('Quantity exceeds the remaining quantity for this stage.');return;}o.progress[d.stage]=old+q;o.history.push({...d,qty:q,rate:Number(d.rate||0),date:new Date().toISOString()});saveMfg();render();});}

